//! Capability index (v1): the discoverability map generated by `vox ci capability-index`.
//!
//! The index is a separate file from the transport-only capability registry
//! (`contracts/capability/capability-registry.yaml`). Every struct serializes every key
//! (`Option` as `null`), so the generator and this loader agree byte-for-byte; serialized key order
//! is declaration order (`serde_json` `preserve_order`).

use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

const EMBEDDED_INDEX_JSON: &str =
    include_str!("../../../contracts/capabilities/capability-index.v1.json");

/// Crates that hold every handler of a surface; their name says nothing about a domain or a
/// sibling capability (Pitfall 9). Shared by the generator's domain rule and the card's Related.
pub const SURFACE_CRATES: [&str; 4] = ["vox-cli", "vox-cli-ci", "vox-orchestrator-mcp", "vox-gui"];

/// Domain ids the generator assigns without a lookup table; `domains.v1.yaml` must define each.
pub const FALLBACK_DOMAIN: &str = "platform";
pub const GUI_DOMAIN: &str = "gui";
pub const SKILLS_DOMAIN: &str = "skills";
pub const DOCS_DOMAIN: &str = "docs";
/// Every id in the group above; the generator rejects a vocabulary missing any.
pub const REQUIRED_DOMAINS: [&str; 4] = [FALLBACK_DOMAIN, GUI_DOMAIN, SKILLS_DOMAIN, DOCS_DOMAIN];

/// Kind of an index row. Declaration order is the sort order of serialized rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RowKind {
    Cli,
    McpTool,
    Surface,
    Crate,
    Skill,
    Doc,
}

/// Graph-coverage snapshot provenance (filled once a snapshot is committed).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CoverageSnapshotMeta {
    pub corpus_id: String,
    pub git_sha: String,
    pub built_at: String,
}

/// A capability domain (grouping label for `vox explain` / `vox features`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DomainDef {
    pub id: String,
    pub label: String,
}

/// CLI projection of a row.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CliRef {
    pub path: Vec<String>,
    /// `"vox "` + path joined by spaces.
    pub invocation: String,
    pub feature_gate: Option<String>,
}

/// MCP projection of a row.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct McpRef {
    pub name: String,
}

/// GUI reach of a row (null until the surface join lands).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GuiRef {
    pub view_key: Option<String>,
    pub nav_label: Option<String>,
    pub representation_tier: Option<String>,
    pub catalog_form: bool,
}

/// Owning crate of a row, with the rule that resolved it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct OwnerRef {
    #[serde(rename = "crate")]
    pub crate_name: String,
    pub layer: Option<u8>,
    pub rule: String,
}

/// A documentation link; `origin` is `default`, `claim` or `pinned`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DocLink {
    pub path: String,
    pub origin: String,
}

/// Graph-coverage verdict for a row; `kind: null` always carries a `reason`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CoverageRef {
    pub kind: Option<String>,
    pub basis: String,
    pub ambiguous: bool,
    pub reason: Option<String>,
}

/// One discoverable capability.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct IndexRow {
    pub id: String,
    pub kind: RowKind,
    pub title: String,
    pub summary: Option<String>,
    pub op_id: Option<String>,
    pub status: Option<String>,
    pub domain: Option<String>,
    pub product_lane: Option<String>,
    pub side_effect_class: Option<String>,
    pub tier: Option<String>,
    pub cli: Option<CliRef>,
    pub mcp: Option<McpRef>,
    pub gui: Option<GuiRef>,
    pub owner: Option<OwnerRef>,
    pub source_path: Option<String>,
    pub docs: Vec<DocLink>,
    pub skills: Vec<String>,
    pub equivalents: Vec<String>,
    pub refs: Vec<String>,
    pub coverage: Option<CoverageRef>,
}

/// The v1 index document.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CapabilityIndex {
    pub schema_version: u32,
    pub generator: String,
    pub coverage_snapshot: Option<CoverageSnapshotMeta>,
    pub domains: Vec<DomainDef>,
    pub rows: Vec<IndexRow>,
}

impl CapabilityIndex {
    /// Look up a row by exact id (`cli.<path>` / `mcp.<tool>`).
    #[must_use]
    pub fn row(&self, id: &str) -> Option<&IndexRow> {
        // ponytail: linear scan over ~1.3k rows; build a map if a hot path ever needs it.
        self.rows.iter().find(|r| r.id == id)
    }

    /// D-03/D-15: the first destructive CLI row whose `cli.path` is an ordered subsequence of the
    /// non-flag tokens of `argv`, or `None`. Flags are dropped so a global flag before the
    /// subcommand (`--json plugin remove`) cannot hide it; a false positive fails closed.
    /// Canonical spellings only; see [`Self::confirmation_required_with`] for clap aliases.
    #[must_use]
    pub fn confirmation_required(&self, argv: &[String]) -> Option<&IndexRow> {
        self.confirmation_required_with(argv, &CliAliases::new())
    }

    /// CR-01: like [`Self::confirmation_required`], but a path segment also matches any alias clap
    /// accepts for the command at that canonical prefix (`models` for `model`).
    #[must_use]
    pub fn confirmation_required_with(
        &self,
        argv: &[String],
        aliases: &CliAliases,
    ) -> Option<&IndexRow> {
        // ponytail: linear scan over ~1.5k rows, filtered to destructive first; build an index if hot.
        let tokens: Vec<&str> = argv
            .iter()
            .map(String::as_str)
            .filter(|t| !t.starts_with('-'))
            .collect();
        self.rows.iter().find(|r| {
            r.kind == RowKind::Cli
                && r.side_effect_class.as_deref() == Some("destructive")
                && r.cli
                    .as_ref()
                    .is_some_and(|c| is_ordered_subsequence(&c.path, &tokens, aliases))
        })
    }
}

/// Canonical command path -> alternate spellings (clap aliases) of that path's LAST segment.
pub type CliAliases = std::collections::HashMap<Vec<String>, Vec<String>>;

/// True when every segment of `path` (or one of its aliases) appears as a whole token, in order
/// (gaps allowed).
fn is_ordered_subsequence(path: &[String], tokens: &[&str], aliases: &CliAliases) -> bool {
    if path.is_empty() {
        return false;
    }
    let mut rest = tokens.iter();
    (0..path.len()).all(|i| {
        let alts = aliases.get(&path[..=i]);
        rest.any(|t| *t == path[i] || alts.is_some_and(|a| a.iter().any(|x| x == t)))
    })
}

/// The index embedded at compile time, parsed once.
#[must_use]
pub fn bundled_index() -> &'static CapabilityIndex {
    static INDEX: OnceLock<CapabilityIndex> = OnceLock::new();
    INDEX.get_or_init(|| {
        serde_json::from_str(EMBEDDED_INDEX_JSON).expect(
            "embedded contracts/capabilities/capability-index.v1.json must parse; run `vox ci capability-index --write`",
        )
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_index_parses_and_lookups_return_none() {
        let doc = r#"{"schema_version":1,"generator":"vox ci capability-index","coverage_snapshot":null,"domains":[],"rows":[]}"#;
        let idx: CapabilityIndex = serde_json::from_str(doc).expect("empty index parses");
        assert!(idx.rows.is_empty());
        assert!(idx.row("cli.check").is_none());
    }

    #[test]
    fn bundled_index_finds_check() {
        let idx = bundled_index();
        let cli = idx.row("cli.check").expect("cli.check row");
        assert_eq!(cli.kind, RowKind::Cli);
        let mcp = idx.row("mcp.vox_check").expect("mcp.vox_check row");
        assert_eq!(mcp.kind, RowKind::McpTool);
    }

    fn gate_index() -> CapabilityIndex {
        let row = |id: &str, path: &[&str], class: Option<&str>| {
            serde_json::json!({
                "id": id, "kind": "cli", "title": id, "summary": null, "op_id": null,
                "status": null, "domain": null, "product_lane": null,
                "side_effect_class": class, "tier": null,
                "cli": {"path": path, "invocation": format!("vox {}", path.join(" ")), "feature_gate": null},
                "mcp": null, "gui": null, "owner": null, "source_path": null,
                "docs": [], "skills": [], "equivalents": [], "refs": [], "coverage": null
            })
        };
        let doc = serde_json::json!({
            "schema_version": 1, "generator": "t", "coverage_snapshot": null, "domains": [],
            "rows": [
                row("cli.plugin.remove", &["plugin", "remove"], Some("destructive")),
                row("cli.features", &["features"], Some("read_only")),
                row("cli.fmt", &["fmt"], None),
            ]
        });
        serde_json::from_value(doc).expect("gate index parses")
    }

    fn argv(tokens: &[&str]) -> Vec<String> {
        tokens.iter().map(|t| (*t).to_string()).collect()
    }

    fn gated_id(idx: &CapabilityIndex, tokens: &[&str]) -> Option<String> {
        idx.confirmation_required(&argv(tokens))
            .map(|r| r.id.clone())
    }

    #[test]
    fn confirmation_required_matches_path() {
        let idx = gate_index();
        assert_eq!(
            gated_id(&idx, &["plugin", "remove", "x"]).as_deref(),
            Some("cli.plugin.remove")
        );
    }

    #[test]
    fn confirmation_required_sees_argv_subcommand() {
        let idx = gate_index();
        // path ["plugin"] + __argv ["remove","x"] assembles to the same argv.
        let mut assembled = argv(&["plugin"]);
        assembled.extend(argv(&["remove", "x"]));
        assert_eq!(
            idx.confirmation_required(&assembled).map(|r| r.id.as_str()),
            Some("cli.plugin.remove")
        );
    }

    #[test]
    fn confirmation_required_skips_flags() {
        let idx = gate_index();
        assert!(gated_id(&idx, &["plugin", "--json", "remove", "x"]).is_some());
        assert!(gated_id(&idx, &["--json", "plugin", "remove"]).is_some());
    }

    #[test]
    fn confirmation_required_ignores_non_destructive() {
        let idx = gate_index();
        assert_eq!(gated_id(&idx, &["features"]), None);
        assert_eq!(gated_id(&idx, &["fmt"]), None);
    }

    #[test]
    fn confirmation_required_empty_and_flags_only() {
        let idx = gate_index();
        assert_eq!(gated_id(&idx, &[]), None);
        assert_eq!(gated_id(&idx, &["--json", "--help"]), None);
    }

    #[test]
    fn confirmation_required_order_matters() {
        let idx = gate_index();
        assert_eq!(gated_id(&idx, &["remove", "plugin"]), None);
    }

    #[test]
    fn confirmation_required_with_matches_aliases_per_segment() {
        let idx = gate_index();
        let mut aliases = CliAliases::new();
        aliases.insert(argv(&["plugin"]), argv(&["plug"]));
        aliases.insert(argv(&["plugin", "remove"]), argv(&["rm"]));
        let hit = |t: &[&str]| {
            idx.confirmation_required_with(&argv(t), &aliases)
                .map(|r| r.id.clone())
        };
        assert_eq!(
            hit(&["plug", "rm", "x"]).as_deref(),
            Some("cli.plugin.remove")
        );
        assert_eq!(hit(&["plugin", "rm"]).as_deref(), Some("cli.plugin.remove"));
        // an alias is only valid at its own prefix
        assert_eq!(hit(&["rm", "plug"]), None);
        // without the table the alias is invisible
        assert_eq!(gated_id(&idx, &["plug", "rm", "x"]), None);
    }

    #[test]
    fn confirmation_required_bundled_plugin_remove() {
        let idx = bundled_index();
        assert_eq!(
            gated_id(idx, &["plugin", "remove", "demo"]).as_deref(),
            Some("cli.plugin.remove")
        );
        assert_eq!(gated_id(idx, &["features"]), None);
    }
}
